import json
from pathlib import Path
from openpyxl import load_workbook
from openpyxl.styles import PatternFill

EXCEL_PATH = Path(r"D:\myproject\mira-ai-lab\mas-failure-attribution\dataset\gaia_dataset_raw\2023\validation\5cfb274c-0207-4aa7-9575-6ac0bd95d9b2.xlsx")

def is_green(rgb: str) -> bool:
    if not rgb or len(rgb) not in (6, 8):
        return False
    rgb = rgb[-6:]
    try:
        r = int(rgb[0:2], 16)
        g = int(rgb[2:4], 16)
        b = int(rgb[4:6], 16)
    except ValueError:
        return False
    return g > r and g > b


def collect_green_cells(path: Path):
    wb = load_workbook(path, data_only=True, read_only=True)
    green = []
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for cell in row:
                fill = cell.fill
                if not isinstance(fill, PatternFill):
                    continue
                color = fill.fgColor or fill.start_color
                rgb = getattr(color, "rgb", None)
                if rgb and is_green(rgb):
                    green.append([cell.row, cell.column])
    return green


def build_graph(coords):
    s = {tuple(c) for c in coords}
    g = {}
    for r, c in s:
        neigh = {(r-1,c), (r+1,c), (r,c-1), (r,c+1)} & s
        g[(r,c)] = neigh
    return g


def is_connected(g):
    if not g:
        return True
    start = next(iter(g))
    seen = {start}
    stack = [start]
    while stack:
        v = stack.pop()
        for nb in g[v]:
            if nb not in seen:
                seen.add(nb)
                stack.append(nb)
    return len(seen) == len(g)


def brute_hamiltonian(g):
    nodes = list(g)
    n = len(nodes)
    if any(len(g[v]) < 2 for v in nodes):
        return None
    def backtrack(path, visited):
        if len(path) == n:
            return path if path[0] in g[path[-1]] else None
        last = path[-1]
        for nb in g[last]:
            if nb not in visited:
                res = backtrack(path+[nb], visited|{nb})
                if res:
                    return res
        return None
    for start in nodes:
        res = backtrack([start], {start})
        if res:
            return res
    return None

if not EXCEL_PATH.is_file():
    print(json.dumps({"error": f"File not found: {EXCEL_PATH}"}))
else:
    green_cells = collect_green_cells(EXCEL_PATH)
    print(json.dumps(green_cells))
    if green_cells:
        g = build_graph(green_cells)
        connected = is_connected(g)
        print("Connected:", connected)
        if connected and len(green_cells) <= 12:
            cycle = brute_hamiltonian(g)
            if cycle:
                print("Hamiltonian cycle:", json.dumps([list(p) for p in cycle]))
            else:
                print("No Hamiltonian cycle found.")
        else:
            if not connected:
                print("Green region is disconnected, so a Hamiltonian cycle is impossible.")
            else:
                print("Too many green cells for brute‑force search; consider using a SAT/ILP solver for larger instances.")
